parameters.jsCode:
// Kiểm tra lệnh và bài (/sua, /anh, /hoantac, /lichsu)
const cmd = $('Khi được gọi').first().json;
const id = Number(cmd.id);
const rows = $('Đọc lịch đăng').all().map(i => i.json);
const row = rows.find(r => Number(r['ID']) === id);
const route = cmd.route;
const isSua = route === 'sua';
const req = String(cmd.request || '').trim();
if (!row) return [{ json: { ok: false, reply: `❌ Không tìm thấy bài #${cmd.id} trong lịch đăng.` } }];
const st = String(row['Trạng thái'] || '').trim();
const rawContent = String(row['Nội dung'] || '');
const rawImage = String(row['Link ảnh'] || '');
const note = String(row['Ghi chú'] || '').trim();
const content = rawContent.split('---***---')[0].trim();
const now = DateTime.now().setZone('Asia/Ho_Chi_Minh').toFormat('dd/MM/yyyy HH:mm');

// ----- Lịch sử phiên bản: đánh số cố định theo thứ tự lưu, bỏ bản trùng -----
let hist = [];
try { hist = $('Đọc lịch sử').all().map(i => i.json).filter(h => h && Number(h['ID']) === id && String(h['Bản cũ'] || '').trim()); } catch (e) {}
const LOAI = { chu: 'Chữ', anh: 'Ảnh', bia: 'Ảnh bìa' };
const cur = { chu: rawContent.trim(), anh: rawImage.trim(), bia: String(row['Ảnh bìa OA'] || '').trim() };
function versions(loai) {
  const list = []; const seen = new Set(); let prevReq = loai === 'bia' ? '/anhbia' : 'AI viết';
  for (const h of hist.filter(x => String(x['Loại'] || '').trim() === LOAI[loai])) {
    const v = String(h['Bản cũ']).trim();
    if (!seen.has(v)) { seen.add(v); list.push({ n: list.length + 1, v, tao: prevReq, luc: String(h['Lúc sửa'] || '').trim() }); }
    prevReq = String(h['Yêu cầu'] || '').trim() || prevReq;
  }
  // Bản đang dùng: nếu chưa có trong lịch sử thì là bản mới nhất (số tiếp theo)
  if (cur[loai] && !seen.has(cur[loai])) list.push({ n: list.length + 1, v: cur[loai], tao: prevReq, luc: '', hienTai: true });
  for (const x of list) if (x.v === cur[loai]) x.dangDung = true;
  return list;
}
const vChu = versions('chu'), vAnh = versions('anh'), vBia = versions('bia');
const LOAI_RX = /^(ảnh\s*bìa|anh\s*bia|anh_bia|ảnh_bìa|bìa|bia|chu|chữ|anh|ảnh)?\s*(\d+)?$/i;
const loaiOf = (s) => !s ? '' : /b[iì]a/i.test(s) ? 'bia' : /^c/i.test(s) ? 'chu' : 'anh';
const TEN = { chu: 'chữ', anh: 'ảnh', bia: 'ảnh bìa' };
const listOf = (l) => l === 'chu' ? vChu : l === 'bia' ? vBia : vAnh;
const dongDau = (s) => (String(s).split('\n').find(l => l.trim()) || '').trim().slice(0, 70);
const soChu = (s) => String(s).split('---***---')[0].split(/\s+/).filter(Boolean).length;

// /lichsu <số> [chu|anh]: liệt kê các bản đã có (xem được ở mọi trạng thái)
if (route === 'lichsu') {
  const chi = loaiOf(req.trim());
  if (chi === 'bia' && !vBia.length) return [{ json: { ok: false, reply: `ℹ️ Bài #${id} chưa có ảnh bìa Zalo OA (gõ /anhbia ${id} để tạo, cần có trước khi /duyet).` } }];
  if (vChu.length + vAnh.length <= 2 && !hist.length) return [{ json: { ok: false, reply: `ℹ️ Bài #${id} chưa sửa lần nào nên chưa có bản cũ.` } }];
  const chuTxt = chi === 'anh' || chi === 'bia' ? '' : `✏️ CHỮ – ${vChu.length} bản:\n` + vChu.slice(-15).map(x =>
    `${x.n}. ${dongDau(x.v)}… (${soChu(x.v)} chữ; tạo bởi: ${String(x.tao).slice(0, 60)})${x.dangDung ? ' ← ĐANG DÙNG' : ''}`).join('\n');
  const anhList = chi === 'chu' ? [] : (chi === 'bia' ? vBia : vAnh).slice(-10);
  return [{ json: { ok: true, route, id, note, chuTxt, anhList, soAnh: (chi === 'bia' ? vBia : vAnh).length, nhan: chi === 'bia' ? 'ảnh bìa' : 'ảnh', soBia: chi === 'bia' ? 0 : vBia.length,
    cuoi: chi === 'bia' ? `👀 Xem 1 bản: "/xem ${id} bia <số bản>"\n↩️ Dùng lại bản cũ: "/hoantac ${id} bia <số bản>"\n🖌️ Tạo bản mới: "/anhbia ${id} <yêu cầu>"` : '',
    ack: `🗂️ Đang lấy lịch sử bài #${id}${anhList.length ? ' (kèm ' + anhList.length + ' ảnh)' : ''}...` } }];
}

// /xem <số> chu|anh <số bản>: gửi toàn văn / ảnh của 1 bản để đọc, không đổi gì
if (route === 'xem') {
  const m = req.match(LOAI_RX) || [];
  let loai = loaiOf(m[1]);
  const so = m[2] ? Number(m[2]) : 0;
  if (!so) return [{ json: { ok: false, reply: `ℹ️ Gõ: /xem ${id} chu <số bản> hoặc /xem ${id} anh <số bản>\n(Xem số bản bằng /lichsu ${id})` } }];
  if (!loai) {
    const c = vChu.some(x => x.n === so), a = vAnh.some(x => x.n === so);
    if (c && a) return [{ json: { ok: false, reply: `ℹ️ Bài #${id} có cả chữ bản ${so} và ảnh bản ${so}. Gõ rõ: /xem ${id} chu ${so} hoặc /xem ${id} anh ${so}` } }];
    loai = c ? 'chu' : 'anh';
  }
  const list = listOf(loai);
  const t = list.find(x => x.n === so);
  if (!t) return [{ json: { ok: false, reply: `ℹ️ Bài #${id} không có ${TEN[loai]} bản ${so} (có bản 1–${list.length}). Gõ /lichsu ${id} để xem.` } }];
  return [{ json: { ok: true, route, id, note,
    head: `👀 BÀI #${id} – ${TEN[loai].toUpperCase()} BẢN ${so}${t.dangDung ? ' (ĐANG DÙNG)' : ''}\n(tạo bởi: ${String(t.tao).slice(0, 80)})`,
    chuTxt: loai === 'chu' ? t.v : '', anhList: loai !== 'chu' ? [t] : [], nhan: TEN[loai], soAnh: 1,
    cuoi: t.dangDung ? `ℹ️ Đây là bản đang dùng. Gõ /lichsu ${id} để xem các bản khác.` : `↩️ Dùng bản này: "/hoantac ${id} ${loai} ${so}"\n👀 Xem bản khác: "/xem ${id} ${loai} <số bản>"`,
    ack: `👀 Đang lấy ${TEN[loai]} bản ${so} của bài #${id}...` } }];
}

if (st !== 'Chờ duyệt' && !(route === 'hoantac' && /b[iì]a/i.test(req) && st === 'Chờ đăng')) return [{ json: { ok: false, reply: `ℹ️ Bài #${id} đang ở trạng thái "${st || 'trống'}". Chỉ sửa được bài "Chờ duyệt".` } }];

// /dungbai <số> + nội dung tự viết: thay toàn bộ chữ, giữ phần chữ ký cuối bài, bản cũ lưu lịch sử để /hoantac
if (route === 'dungbai') {
  const body = String(cmd.request || '').replace(/\r/g, '').split('---***---')[0].replace(/\n{3,}/g, '\n\n').trim();
  if (body.split(/\s+/).filter(Boolean).length < 15) return [{ json: { ok: false, reply: `ℹ️ Gõ /dungbai ${id} rồi XUỐNG DÒNG dán toàn bộ bài của bạn vào CÙNG 1 tin nhắn.\nVí dụ:\n/dungbai ${id}\nTIÊU ĐỀ BÀI...\nNội dung bài...\n(Bot tự thêm phần chữ ký GOSTECH ở cuối, ảnh giữ nguyên.)` } }];
  const i = rawContent.indexOf('---***---');
  const full = i >= 0 ? body + '\n\n' + rawContent.slice(i).trim() : body;
  if (full.trim() === rawContent.trim()) return [{ json: { ok: false, reply: `ℹ️ Nội dung gửi giống hệt bài #${id} hiện tại, không đổi gì.` } }];
  return [{ json: { ok: true, route, id, req: '/dungbai', content, note, loai: 'chu', old: full, soBan: vChu.length + (vChu.some(x => x.v === full) ? 0 : 1),
    luuLoai: 'Chữ', luuBan: cur.chu, luuYeuCau: '/dungbai (bài tự viết)',
    restore: { 'ID': String(id), 'Nội dung': full, 'Link ảnh': rawImage, 'Ảnh bìa OA': cur.bia,
      'Ghi chú': [note, `Dùng bài tự viết qua Zalo ${now} (${soChu(full)} chữ)`].filter(Boolean).join(' | ') },
    ack: `📝 Đang thay nội dung bài #${id} bằng bài bạn gửi...` } }];
}

// /hoantac <số bài> [chu|anh] [số bản]
if (route === 'hoantac') {
  const m = req.match(LOAI_RX) || [];
  let loai = loaiOf(m[1]);
  const soBan = m[2] ? Number(m[2]) : 0;
  let target = null;
  if (soBan) {
    if (!loai) {
      const coChu = vChu.some(x => x.n === soBan), coAnh = vAnh.some(x => x.n === soBan);
      if (coChu && coAnh) return [{ json: { ok: false, reply: `ℹ️ Bài #${id} có cả chữ bản ${soBan} và ảnh bản ${soBan}. Gõ rõ: /hoantac ${id} chu ${soBan} hoặc /hoantac ${id} anh ${soBan}` } }];
      loai = coChu ? 'chu' : 'anh';
    }
    const list = listOf(loai);
    target = list.find(x => x.n === soBan);
    if (!target) return [{ json: { ok: false, reply: `ℹ️ Bài #${id} không có ${TEN[loai]} bản ${soBan} (có bản 1–${list.length}). Gõ /lichsu ${id} để xem.` } }];
    if (target.dangDung) return [{ json: { ok: false, reply: `ℹ️ Bài #${id} đang dùng đúng ${TEN[loai]} bản ${soBan} rồi.` } }];
  } else {
    // Không ghi số: quay lại bản ngay trước bản đang dùng (lần thay đổi gần nhất)
    const keyOf = (x) => x === 'Ảnh bìa' ? 'bia' : x === 'Ảnh' ? 'anh' : 'chu';
    const cand = hist.filter(h => loai ? String(h['Loại']).trim() === LOAI[loai] : String(h['Loại']).trim() !== 'Ảnh bìa')
      .filter(h => String(h['Bản cũ']).trim() !== cur[keyOf(String(h['Loại']).trim())]).pop();
    if (!cand) return [{ json: { ok: false, reply: `ℹ️ Bài #${id} không còn bản ${loai ? TEN[loai] + ' ' : ''}cũ nào để quay lại. Gõ /lichsu ${id} để xem.` } }];
    loai = keyOf(String(cand['Loại']).trim());
    target = listOf(loai).find(x => x.v === String(cand['Bản cũ']).trim());
  }
  const old = target.v;
  return [{ json: { ok: true, route, id, req, content, note, loai, old, soBan: target.n,
    luuLoai: LOAI[loai], luuBan: cur[loai], luuYeuCau: `/hoantac về ${TEN[loai]} bản ${target.n}`,
    restore: { 'ID': String(id), 'Nội dung': loai === 'chu' ? old : rawContent, 'Link ảnh': loai === 'anh' ? old : rawImage, 'Ảnh bìa OA': loai === 'bia' ? old : cur.bia,
      'Ghi chú': [note, `Hoàn tác qua Zalo ${now}: về ${TEN[loai]} bản ${target.n}`].filter(Boolean).join(' | ') },
    ack: `↩️ Đang đưa bài #${id} về ${loai === 'chu' ? 'nội dung' : TEN[loai]} bản ${target.n}...` } }];
}

if (isSua && !req) return [{ json: { ok: false, reply: `ℹ️ Gõ kèm yêu cầu sửa, ví dụ: /sua ${id} viết ngắn lại, thêm emoji đầu mỗi ý` } }];
// /sua mà yêu cầu chỉ nói về ẢNH -> nhắc dùng /anh, không sửa chữ
const veAnh = /(ảnh|hình|thiết kế|banner|poster|logo)/i.test(req);
const veChu = /(chữ|nội dung|content|bài viết|viết|câu|đoạn|tiêu đề|hook|emoji|văn|chính tả|ngắn|dài|chi tiết|cụ thể|giọng)/i.test(req);
if (isSua && veAnh && !veChu) return [{ json: { ok: false, reply: `ℹ️ Yêu cầu này là về ẢNH nên bot không sửa chữ.\n🖼️ Gõ: /anh ${id} ${req}\n(Mỗi bài hiện có 1 ảnh bìa, bot chưa làm bộ nhiều ảnh.)` } }];

// Yêu cầu viết dài / chi tiết hơn -> nâng giới hạn chữ và bắt buộc dài hơn rõ rệt
const oldWords = content.split(/\s+/).filter(Boolean).length;
const dai = isSua && /(chi tiết|dài hơn|dài ra|viết dài|cụ thể|mở rộng|đầy đủ hơn|kỹ hơn|kĩ hơn|ngắn quá|quá ngắn|hơi ngắn|thêm nội dung|giải thích thêm|sâu hơn)/i.test(req);
const ngan = isSua && /(ngắn|rút gọn|cô đọng|gọn lại|bớt chữ|tóm tắt|giảm số chữ)/i.test(req);
const vietLai = /(viết lại|hay hơn|hấp dẫn|cuốn hút|chuyên nghiệp hơn|giọng|phong cách|toàn bộ|cả bài|thay đổi nhiều|sáng tạo|mới hoàn toàn)/i.test(req);
const nho = isSua && !dai && !ngan && !vietLai;   // mặc định: yêu cầu cụ thể -> chỉ sửa đúng chỗ
const maxTu = dai ? Math.min(600, Math.max(450, Math.round(oldWords * 2.2))) : ngan ? Math.max(120, Math.round(oldWords * 0.8)) : Math.max(300, Math.round(oldWords * 1.15));
const them = (dai ? `\n\nYÊU CẦU VIẾT DÀI/CHI TIẾT: bài hiện có ${oldWords} chữ, bài mới phải dài ít nhất ${Math.round(oldWords * 1.6)} chữ (tối đa ${maxTu}). Giữ các ý chính, nhưng ngay dưới MỖI ý viết thêm 1-2 câu giải thích cụ thể (làm ở đâu, bấm gì, ví dụ ngắn). Không được chỉ đổi vài chữ.` : '')
  + (isSua && veAnh ? '\n\nPHẦN NÀO TRONG YÊU CẦU NÓI VỀ ẢNH (thiết kế ảnh, thêm ảnh, màu của ảnh) thì BỎ QUA, không đưa vào nội dung bài.' : '');
const nhieuAnh = !isSua && /(\d+|nhiều|bộ|thêm)\s*(ảnh|hình)/i.test(req);
return [{ json: { ok: true, route, id, req, content, rawContent, rawImage, layoutNow: ((note.match(/bố cục: ([a-z_0-9]+)/g) || []).map(x => x.replace('bố cục: ', '')).pop() || ''),
  note, dai, oldWords, maxTu, nho, ngan,
  them: them + (nho ? '\n\nĐÂY LÀ YÊU CẦU SỬA CỤ THỂ: chỉ thay đổi ĐÚNG phần được yêu cầu (và chỗ liên quan trực tiếp). Mọi câu, đoạn, tiêu đề, hook, emoji, xuống dòng khác phải GIỮ NGUYÊN TỪNG CHỮ như bài hiện tại. Không viết lại, không rút gọn, không thêm ý mới, không đổi giọng văn.' : ''), nhacAnh: isSua && veAnh,
  ack: isSua ? `✏️ Đang sửa chữ bài #${id} theo yêu cầu, chờ khoảng 30 giây...` : `🖼️ Đang tạo lại ảnh bài #${id}, chờ khoảng 1 phút...` + (nhieuAnh ? '\n(Mỗi bài hiện có 1 ảnh bìa: bot làm lại 1 ảnh theo yêu cầu.)' : '') } }];

parameters.jsonBody:
={{ JSON.stringify({
  systemInstruction: { parts: [{ text: `Bạn là chuyên gia viết content viral hơn 10 năm kinh nghiệm, viết cho fanpage "Học Viện Digital - GOS Academy". Nhiệm vụ: SỬA bài viết dưới đây theo YÊU CẦU SỬA của người duyệt. Phải thực hiện ĐÚNG, ĐỦ và THẤY RÕ từng ý trong yêu cầu (ví dụ yêu cầu thêm emoji đầu mỗi ý thì MỖI dòng ý đều phải bắt đầu bằng một emoji phù hợp). ${$('Kiểm tra').first().json.nho ? 'Đây là yêu cầu sửa CỤ THỂ: chỉ sửa đúng chỗ được yêu cầu, giữ nguyên từng chữ toàn bộ phần còn lại (kể cả HOOK, các ý, emoji, xuống dòng);' : 'Người duyệt phải nhìn thấy ngay bài đã khác: được viết lại câu chữ, thêm/bớt/đổi ý khi cần để đáp ứng yêu cầu; chỉ giữ chủ đề và kiểu trình bày;'} DÒNG ĐẦU TIÊN (tiêu đề) phải giữ nguyên từng chữ, trừ khi yêu cầu nói đổi tiêu đề. Không dùng dấu nháy ngược hay markdown cho tên hàm/code. ${$('Kiểm tra').first().json.nho ? 'Không được viết lại hay rút gọn phần không liên quan đến yêu cầu.' : 'TUYỆT ĐỐI không trả lại bài gần như y nguyên.'} Nội dung phải cụ thể, thực chiến (làm ở đâu, hàm/công thức gì, ví dụ thật), không dùng câu sáo rỗng chung chung. Luật bắt buộc:
1. TỐI ĐA ${$('Kiểm tra').first().json.maxTu || 300} từ, đếm cả tiêu đề – vượt là SAI (chi tiết nghĩa là cụ thể hơn, không phải dài lê thê; không chèn đoạn code dài)
2. BẮT BUỘC xuống dòng thật sự bằng ký tự xuống dòng (trong chuỗi JSON viết là \\n), TUYỆT ĐỐI không dùng dấu hai chấm thay cho xuống dòng: HOOK một dòng riêng, mỗi ý trong danh sách là một dòng riêng, giữa các phần cách một dòng trống (một dòng trống). Không viết dồn một đoạn
3. HOOK viết in hoa. Giữ nguyên KIỂU VIẾT và cách dùng emoji hiện có của bài (kể chuyện, hỏi đáp, danh sách...), trừ khi yêu cầu sửa nói đổi
4. Không dùng markdown hay ký tự **. Dòng đánh dấu ảnh dạng [ảnh 2] (đứng riêng 1 dòng) phải giữ nguyên đúng như vậy và đứng sau đúng đoạn/ý mà nó đang đứng sau trong bài hiện tại; không thêm, không bỏ dòng đánh dấu
5. Không viết thông tin liên hệ/chữ ký cuối bài (hệ thống tự thêm)
6. Không bịa số liệu, giá, ưu đãi, cam kết không có trong bài hoặc yêu cầu
Trả JSON: "content" là bài đã sửa hoàn chỉnh, "tom_tat" là 1-2 câu nêu CỤ THỂ những gì đã thay đổi (ví dụ: thêm giải thích cho 5 bước, viết lại câu mở đầu, bỏ đoạn kết cũ).` }] },
  contents: [{ role: 'user', parts: [{ text: 'BÀI HIỆN TẠI:\n' + $('Kiểm tra').first().json.content + '\n\nYÊU CẦU SỬA: ' + $('Kiểm tra').first().json.req + ($('Kiểm tra').first().json.them || '') + (() => { try { const v = JSON.parse($('Kiểm tra yêu cầu').first().json.candidates[0].content.parts.map(p => p.text || '').join('')); return v.ok ? '' : '\n\nLẦN SỬA TRƯỚC CÒN THIẾU: ' + v.thieu + ' (lần này phải làm đủ).'; } catch (e) { return ''; } })() }] }],
  generationConfig: { temperature: 0.7, responseMimeType: 'application/json',
    responseSchema: { type: 'OBJECT', properties: { content: { type: 'STRING' }, tom_tat: { type: 'STRING' } }, required: ['content', 'tom_tat'] } }
}) }}

={{ JSON.stringify({
