const H = (s) => { let h = 5381; for (const ch of String(s || '')) h = ((h * 33) ^ ch.charCodeAt(0)) >>> 0; return h.toString(36); };
const row = $('Đọc lịch đăng').all().map(i => i.json).find(x => Number(x['ID']) === Number(k.id)) || {};
