// Soạn tin báo đã quay lại bản trước
const lenh = (id) => `👉 "/duyet ${id}" để đăng lúc 19:30, hoặc hẹn giờ: "/duyet ${id} 20:15" | "/bo ${id}" để bỏ\n✏️ "/sua ${id} <yêu cầu>" để AI sửa chữ | 📝 "/dungbai ${id}" + xuống dòng dán bài tự viết (cùng 1 tin) để thay toàn bộ chữ\n🖼️ "/anh ${id}" để AI vẽ lại ảnh (có thể kèm yêu cầu) | "/anh ${id} ngang" vẽ ảnh ngang 16:9 (đứng đầu album, dùng luôn làm ảnh bìa OA)
📎 Dùng ảnh tự thiết kế: gửi ảnh hoặc file ảnh vào nhóm rồi gõ "/dunganh ${id}" (ảnh vuông = ảnh bài, ảnh ngang = ảnh bìa Zalo OA)\n➕ "/themanh ${id}" thêm các ảnh vừa gửi (1 bài nhiều ảnh) | ➖ "/xoaanh ${id} <số ảnh>"
🖌️ "/anhbia ${id}" để tạo ảnh bìa Zalo OA (cần có trước khi /duyet)\n↩️ "/hoantac ${id}" quay lại bản ngay trước | "/hoantac ${id} chu|anh|bia <số bản>" về đúng bản đó
🗂️ "/lichsu ${id}" xem các bản chữ + ảnh, "/lichsu ${id} bia" xem ảnh bìa | 👀 "/xem ${id} chu|anh|bia <số bản>" xem 1 bản
⏰ "/hengio ${id} <giờ>" đổi giờ đăng | 📋 "/choduyet" xem các bài đang chờ`;
function splitMsgs(text) {
  const out = []; const max = 1900; let cur = '';
  for (const para of String(text).split(/\n{2,}/)) {
    const joined = cur ? cur + '\n\n' + para : para;
    if (joined.length <= max) { cur = joined; continue; }
    if (cur) out.push({ text: cur });
    cur = para.length <= max ? para : '';
    if (para.length > max) for (let i = 0; i < para.length; i += max) out.push({ text: para.slice(i, i + max) });
  }
  if (cur) out.push({ text: cur });
  return out;
}
const k = $('Kiểm tra').first().json;
let msgs;
if (k.loai === 'chu') {
  const head = k.route === 'dungbai' ? `📝 BÀI #${k.id} ĐÃ DÙNG NỘI DUNG BẠN GỬI (bản ${k.soBan})\n(Ảnh giữ nguyên, đã giữ phần chữ ký cuối bài. Muốn quay lại bài cũ: /hoantac ${k.id})`
                                    : `↩️ BÀI #${k.id} ĐÃ VỀ NỘI DUNG BẢN ${k.soBan}\n(Ảnh giữ nguyên)`;
  let att = null; try { att = $('Zalo: tải ảnh cũ').first().json.data?.attachment_id || null; } catch (e) {}
  msgs = [att ? { text: head, attachment: { type: 'template', payload: { template_type: 'media', elements: [{ media_type: 'image', attachment_id: att }] } } } : { text: head }, ...splitMsgs(k.old), { text: lenh(k.id) }];
} else {
  let att = null; try { att = $('Zalo: tải ảnh cũ').first().json.data?.attachment_id || null; } catch (e) {}
  const head = k.loai === 'bia' ? `↩️ BÀI #${k.id} ĐÃ VỀ ẢNH BÌA ZALO OA BẢN ${k.soBan}\n(Chữ và ảnh bài giữ nguyên)` : `↩️ BÀI #${k.id} ĐÃ VỀ ẢNH BẢN ${k.soBan}\n(Chữ giữ nguyên)`;
  msgs = [att ? { text: head, attachment: { type: 'template', payload: { template_type: 'media', elements: [{ media_type: 'image', attachment_id: att }] } } }
              : { text: head + '\n⚠️ Chưa gửi được ảnh vào Zalo, xem ảnh ở cột Link ảnh trong Sheet.' }, { text: lenh(k.id) }];
}
return msgs.map(message => ({ json: { message } }));

// Mỗi ảnh cũ 1 item để tải về và gửi vào nhóm kèm số bản
const k = $('Kiểm tra').first().json;
const list = k.anhList || [];
if (!list.length) return [{ json: { none: true, url: '' } }];
return list.map(x => ({ json: { n: x.n, url: x.v, tao: x.tao, dangDung: !!x.dangDung } }));

// Soạn tin lịch sử: danh sách chữ + từng ảnh cũ kèm số bản
const k = $('Kiểm tra').first().json;
const imgs = $('Danh sách ảnh cũ').all().map(i => i.json);
let ups = []; try { ups = $('Zalo: tải ảnh bản cũ').all().map(i => i.json); } catch (e) {}
const msgs = [];
const head = k.head || `🗂️ LỊCH SỬ BÀI #${k.id}`;
if (k.chuTxt) {
  const t = head + (k.route === 'xem' ? '\n\n' : '\n') + k.chuTxt;
  for (let i = 0; i < t.length; i += 1900) msgs.push({ text: t.slice(i, i + 1900) });
} else if (k.route !== 'xem') msgs.push({ text: head });
if (!imgs[0]?.none) {
  if (k.route !== 'xem') msgs.push({ text: `🖼️ ${(k.nhan || 'ảnh').toUpperCase()} – ${k.soAnh} bản${k.soAnh > imgs.length ? ' (hiện ' + imgs.length + ' bản mới nhất)' : ''}:` });
  imgs.forEach((x, i) => {
    const cap = `🖼️ Bài #${k.id} – ${k.nhan || 'ảnh'} bản ${x.n}${x.dangDung ? ' ← ĐANG DÙNG' : ''}\n(tạo bởi: ${String(x.tao).slice(0, 80)})`;
    const att = ups[i]?.data?.attachment_id;
    msgs.push(att ? { text: cap, attachment: { type: 'template', payload: { template_type: 'media', elements: [{ media_type: 'image', attachment_id: att }] } } }
                  : { text: cap + '\n⚠️ Không tải được ảnh này (link cũ có thể đã hết hạn).' });
  });
}
msgs.push({ text: k.cuoi || `👀 Đọc đầy đủ 1 bản: "/xem ${k.id} chu <số bản>"\n↩️ Về đúng bản muốn dùng: "/hoantac ${k.id} chu <số bản>" hoặc "/hoantac ${k.id} anh <số bản>"\n(Bản đang dùng vẫn được lưu lại, không mất bản nào.)${k.soBia ? '\n🖼️ Ảnh bìa Zalo OA: ' + k.soBia + ' bản – xem: "/lichsu ' + k.id + ' bia"' : ''}` });
return msgs.map(message => ({ json: { message } }));

parameters.jsonBody:
={{ JSON.stringify({
  systemInstruction: { parts: [{ text: `Bạn là chuyên gia viết content viral hơn 10 năm kinh nghiệm, viết cho fanpage "Học Viện Digital - GOS Academy". Nhiệm vụ: SỬA bài viết dưới đây theo YÊU CẦU SỬA của người duyệt. Phải thực hiện ĐÚNG, ĐỦ và THẤY RÕ từng ý trong yêu cầu (ví dụ yêu cầu thêm emoji đầu mỗi ý thì MỖI dòng ý đều phải bắt đầu bằng một emoji phù hợp). ${$('Kiểm tra').first().json.nho ? 'Đây là yêu cầu sửa CỤ THỂ: chỉ sửa đúng chỗ được yêu cầu, giữ nguyên từng chữ toàn bộ phần còn lại (kể cả HOOK, các ý, emoji, xuống dòng);' : 'Người duyệt phải nhìn thấy ngay bài đã khác: được viết lại câu chữ, thêm/bớt/đổi ý khi cần để đáp ứng yêu cầu; chỉ giữ chủ đề và kiểu trình bày;'} DÒNG ĐẦU TIÊN (tiêu đề) phải giữ nguyên từng chữ, trừ khi yêu cầu nói đổi tiêu đề. Không dùng dấu nháy ngược hay markdown cho tên hàm/code. ${$('Kiểm tra').first().json.nho ? 'Không được viết lại hay rút gọn phần không liên quan đến yêu cầu.' : 'TUYỆT ĐỐI không trả lại bài gần như y nguyên.'} Nội dung phải cụ thể, thực chiến (làm ở đâu, hàm/công thức gì, ví dụ thật), không dùng câu sáo rỗng chung chung. Luật bắt buộc:
1. TỐI ĐA ${$('Kiểm tra').first().json.maxTu || 300} từ, đếm cả tiêu đề – vượt là SAI (chi tiết nghĩa là cụ thể hơn, không phải dài lê thê; không chèn đoạn code dài)
2. BẮT BUỘC xuống dòng thật sự bằng ký tự xuống dòng (trong chuỗi JSON viết là \\n), TUYỆT ĐỐI không dùng dấu hai chấm thay cho xuống dòng: HOOK một dòng riêng, mỗi ý trong danh sách là một dòng riêng, giữa các phần cách một dòng trống (một dòng trống). Không viết dồn một đoạn
3. HOOK viết in hoa. Giữ nguyên KIỂU VIẾT và cách dùng emoji hiện có của bài (kể chuyện, hỏi đáp, danh sách...), trừ khi yêu cầu sửa nói đổi
4. Không dùng markdown hay ký tự **. Dòng đánh dấu ảnh dạng [ảnh 2] (đứng riêng 1 dòng) phải giữ nguyên đúng như vậy và đứng sau đúng đoạn/ý mà nó đang đứng sau trong bài hiện tại; không thêm, không bỏ dòng đánh dấu
